// spec: specs/business-cards-images.md (2.3) · кейс: .qa/tests/business-cards-images/CARDIMG-10
// #494e0b: при загрузке картинки однотонные поля обрезаются — и в оригинале, и в ….card3.webp; контроль без полей не меняется.
// seed: tests/seed.user.spec.ts · ПРОД, ПИШУЩИЙ (@data): черновик «QA-TEST QA-AUTO 494e0b …» под user, удаляется в afterEach
// (корзина в /mybusinesses, запасной путь — API DELETE с content-profile; проверка GET = пусто).
// В storage остаются 3 оригинала + 3 .card3.webp на прогон (сайт их не удаляет) — имена с QA-AUTO-494e0b, в отчёт.
// Запуск только: QA_REAL_WRITE=1 npx playwright test card-trim-upload --project=tests --workers 1
import { test, expect } from '@playwright/test';
import {
  Ctl, LOAD, NEXT, REAL_WRITE, SKIP_REASON, CAFES, cleanup, fillCommon, newTitle, openNewWizard, prepare, submitStep1,
} from '../addbusiness-draft-save/draft-reopen.helpers';
import { SAMPLES, STEP3_HEADING, allowUploads, makeJpeg, natural, publicUrl, uploadSample } from './card-trim-upload.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

let ctl: Ctl | null = null;

test.beforeEach(() => {
  test.skip(!REAL_WRITE, SKIP_REASON);
});

test.afterEach(async ({ page }, info) => {
  if (!ctl) return;
  const log = await cleanup(page, ctl);
  info.annotations.push({ type: 'cleanup', description: log.join('; ') || 'черновик не создавался' });
  ctl = null;
});

const RATIO_TOL = 0.02;

test.describe('Обрезка однотонных полей картинки карточки (#494e0b)', () => {
  test('новая загрузка: чёрные и белые поля обрезаются, контроль не меняется #494e0b @desktop @data', async ({ page, context }) => {
    test.setTimeout(240_000);
    ctl = await prepare(context, newTitle('trim', '494e0b'));
    const uploads = await allowUploads(context);

    await openNewWizard(page);
    await fillCommon(page, ctl, CAFES);
    await submitStep1(page, ctl);
    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByRole('heading', { name: STEP3_HEADING, exact: true }), 'шаг 3 — фото').toBeVisible(LOAD);

    const stored: string[] = [];
    const sizes: Record<string, { orig: [number, number] | null; card3: [number, number] | null }> = {};
    for (const s of SAMPLES) {
      const buf = await makeJpeg(page, s);
      const up = await uploadSample(page, uploads, s, buf);
      const o = publicUrl(up.orig);
      const c = publicUrl(up.card3);
      stored.push(up.orig.path, up.card3.path);
      sizes[s.tag] = { orig: await natural(page, o), card3: await natural(page, c) };
    }
    test.info().annotations.push({ type: 'storage (остаются, удалить вручную при необходимости)', description: stored.join(', ') });
    test.info().annotations.push({ type: 'размеры', description: JSON.stringify(sizes) });

    // A: 400×1000 с чёрными полями 300 сверху/снизу → 400×400.
    expect(sizes['black-tb'].orig, 'A (чёрные поля сверху/снизу): оригинал 400×400').toEqual([400, 400]);
    expect(sizes['black-tb'].card3, 'A: card3 400×400').toEqual([400, 400]);
    // B: 1000×400 с белыми полями 300 слева/справа → 400×400.
    expect(sizes['white-lr'].orig, 'B (белые поля слева/справа): оригинал 400×400').toEqual([400, 400]);
    expect(sizes['white-lr'].card3, 'B: card3 400×400').toEqual([400, 400]);
    // C: контроль 800×600 без полей — оригинал не меняется, card3 в пропорции 4:3.
    expect(sizes['nomargin'].orig, 'C (без полей): оригинал 800×600 без изменений').toEqual([800, 600]);
    const c3 = sizes['nomargin'].card3;
    expect(c3, 'C: card3 загрузился').not.toBeNull();
    expect(Math.abs(c3![0] / c3![1] - 4 / 3) / (4 / 3), `C: card3 ${c3!.join('×')} в пропорции 4:3`).toBeLessThanOrEqual(RATIO_TOL);
  });
});
